CREATE EXTENSION IF NOT EXISTS vector;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, account_role text NOT NULL DEFAULT 'student' CHECK(account_role IN ('student','professor')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orgs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL, description text NOT NULL DEFAULT '', join_code text UNIQUE NOT NULL DEFAULT upper(substr(encode(gen_random_bytes(6),'hex'),1,10)), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships (user_id uuid NOT NULL REFERENCES users(id), org_id uuid NOT NULL REFERENCES orgs(id), role text NOT NULL CHECK(role IN ('student','faculty')), PRIMARY KEY(user_id,org_id));
CREATE TABLE IF NOT EXISTS blobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scope_type text NOT NULL CHECK(scope_type IN ('user','org')), scope_id uuid NOT NULL, sha256 text NOT NULL, size_bytes bigint NOT NULL, storage_key text UNIQUE NOT NULL, ref_count int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(scope_type,scope_id,sha256));
CREATE TABLE IF NOT EXISTS files (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_type text NOT NULL CHECK(owner_type IN ('user','org')), owner_id uuid NOT NULL, name text NOT NULL, format text NOT NULL CHECK(format IN ('docx','pptx','pdf','quiz')), kind text NOT NULL CHECK(kind IN ('upload','generated')), searchable boolean NOT NULL DEFAULT true, visibility text NOT NULL DEFAULT 'classroom' CHECK(visibility IN ('classroom','selected')), current_version_id uuid, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), archived_at timestamptz, deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS file_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), file_id uuid NOT NULL REFERENCES files(id), version_no int NOT NULL, blob_id uuid NOT NULL REFERENCES blobs(id), original_name text NOT NULL, size_bytes bigint NOT NULL, sha256 text NOT NULL, status text NOT NULL CHECK(status IN ('processing','ready','failed')), error text, unit_count int NOT NULL DEFAULT 0, uploaded_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), retracted_at timestamptz, retract_reason text, UNIQUE(file_id,version_no));
CREATE TABLE IF NOT EXISTS file_shares (file_id uuid NOT NULL REFERENCES files(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, shared_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(file_id,user_id));
DO $$ BEGIN ALTER TABLE files ADD CONSTRAINT files_current_version_fk FOREIGN KEY(current_version_id) REFERENCES file_versions(id); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS units (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version_id uuid NOT NULL REFERENCES file_versions(id) ON DELETE CASCADE, idx int NOT NULL, locator text NOT NULL, text text NOT NULL, text_hash text NOT NULL, char_count int NOT NULL, embedding vector(768), UNIQUE(version_id,idx));
CREATE INDEX IF NOT EXISTS units_hash_idx ON units(text_hash);
CREATE TABLE IF NOT EXISTS lineage_edges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), from_version_id uuid NOT NULL REFERENCES file_versions(id) ON DELETE CASCADE, to_version_id uuid NOT NULL REFERENCES file_versions(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN ('revision','derived')), stats jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(from_version_id,to_version_id,kind));
CREATE TABLE IF NOT EXISTS near_duplicate_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), version_id uuid NOT NULL REFERENCES file_versions(id) ON DELETE CASCADE, matched_version_id uuid NOT NULL REFERENCES file_versions(id) ON DELETE CASCADE, match_fraction real NOT NULL, status text NOT NULL DEFAULT 'flagged' CHECK(status IN ('flagged','dismissed')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lifecycle_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), file_id uuid NOT NULL REFERENCES files(id), created_by uuid NOT NULL REFERENCES users(id), type text NOT NULL CHECK(type IN ('AFTER_DAYS','WHEN_FILE_UPDATED')), params jsonb NOT NULL, state text NOT NULL DEFAULT 'dry_run' CHECK(state IN ('dry_run','active','fired','disabled')), activates_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lifecycle_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), file_id uuid NOT NULL REFERENCES files(id), rule_id uuid REFERENCES lifecycle_rules(id), action text NOT NULL CHECK(action IN ('archive','would_archive','unarchive')), reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
